<?php
$pageTitle='Departments';$activePage='department.php';require __DIR__.'/../includes/admin_layout.php';
if ($_SERVER['REQUEST_METHOD']==='POST' && trim((string)($_POST['name']??''))!=='') { $insert=$pdo->prepare('INSERT INTO departments (name,description) VALUES (?,?)');$insert->execute([trim($_POST['name']),trim($_POST['description']??'')]); }
$departments=$pdo->query('SELECT d.id,d.name,d.description,COUNT(u.id) people FROM departments d LEFT JOIN users u ON u.department_id=d.id GROUP BY d.id ORDER BY d.id')->fetchAll();
?>
<div class="admin-heading"><div><h1>Departments</h1><p>Organize your workforce, assign accountable owners, and keep staffing balanced.</p></div><div class="admin-actions"><a class="admin-btn primary" href="#add-department">+ Add department</a></div></div><div class="metric-grid"><div class="metric-card"><small>Departments</small><strong><?= count($departments) ?></strong><span>Active workspace teams</span></div><div class="metric-card"><small>Total people</small><strong><?= array_sum(array_column($departments,'people')) ?></strong><span>Employees, interns and agents</span></div><div class="metric-card"><small>Department owners</small><strong><?= count($departments) ?></strong><span>Clear ownership</span></div><div class="metric-card"><small>Unassigned people</small><strong>0</strong><span>Every person has a team</span></div></div>
<section class="admin-panel data-panel"><table class="admin-table"><thead><tr><th>Department</th><th>Description</th><th>People assigned</th><th>Status</th></tr></thead><tbody><?php foreach($departments as $department): ?><tr><td><?= htmlspecialchars($department['name']) ?></td><td><?= htmlspecialchars($department['description']) ?></td><td><?= $department['people'] ?></td><td><span class="badge">Active</span></td></tr><?php endforeach; ?></tbody></table></section>
<section id="add-department" class="admin-panel" style="margin-top:16px"><h2>Add a department</h2><form method="post" class="table-toolbar"><input name="name" required placeholder="Department name"><input name="description" placeholder="Short description"><button class="admin-btn primary" type="submit">Save department</button></form></section><?php require __DIR__.'/../includes/admin_footer.php'; ?>